#!/usr/bin/env python3
"""Current executable acceptance using fixtures generated by this source build."""
from pathlib import Path
import json
import shutil
from build_support import ROOT, artifact_path, config, digest, isolated_env, run, workspace
from verify_network import verify as verify_network


def main():
    settings = config()
    manifest_path = ROOT / 'outputs' / (settings['artifact_id'] + '-build-manifest.json')
    manifest = json.loads(manifest_path.read_text())
    assert manifest['stem'] == settings['stem']
    assert manifest['source_suites'] and all(v == 'PASS' for v in manifest['source_suites'].values())
    assert len(manifest['source_suites']) == len(list((ROOT / 'game/tests').glob('test_*.gd')))
    for build in manifest['builds']:
        assert digest(artifact_path(ROOT, build['file'])) == build['sha256'], 'Stale binary'
    binary = artifact_path(ROOT, next(x['file'] for x in manifest['builds'] if x['platform'] == 'Linux'))
    directory = workspace('acceptance')
    env = isolated_env(directory)
    data = directory / 'data/godot/app_userdata/Moonstone Remake'

    def probe(name, arguments, prefix='', *, executable=binary, case_env=env, cwd=ROOT):
        text = run([executable, '--headless', '--audio-driver', 'Dummy', '--fixed-fps', '50', '--', *arguments], directory / (name + '.log'), env=case_env, cwd=cwd, timeout=45)
        assert 'PASS:' in text, name
        if not prefix:
            return 'PASS'
        line = next(line for line in text.splitlines() if line.startswith(prefix))
        return json.loads(line[len(prefix):])

    normal = probe('normal', ['--smoke', '--equipment-demo', '--cooperative', '--debug-mode-probe'], 'LAUNCH_MODE_STATE=')
    assert not any(normal[k] for k in ['debug', 'equipment_demo', 'map_demo', 'campaign_demo', 'arena', 'practice'])
    assert normal['mode'] == 'competitive' and normal['xp'] == 0
    controllers = probe('controller', ['--debug', '--controller-probe'], 'CONTROLLER_STATE=')
    assert not controllers['failures'] and controllers['checks'] >= 787 and controllers['cursor_alignment_checks'] >= 14
    golden = json.loads((ROOT / 'game/tests/fixtures/combat_traces.json').read_text())
    assert controllers['session_traces'] == golden['session_traces'], 'Combat trace changed'
    layers = probe('layered-graphics', ['--debug', '--layered-graphics-probe'], 'LAYERED_GRAPHICS_STATE=')
    assert not layers['failures'] and layers['families'] == 37 and layers['layer_draws'] > 0 and layers['other_regions'] == 0
    practice = probe('practice', ['--debug', '--practice-probe'], 'PRACTICE_STATE=')
    assert not practice['failures'] and practice['checks'] >= 570 and len(practice['replays']) == 12 and practice['file_isolation'] == 'PASS'
    party = probe('party', ['--debug', '--local-players-probe'], 'LOCAL_PLAYERS_STATE=')
    assert not party['failures'] and party['checks'] >= 136
    guard = probe('debug-guard', ['--debug', '--debug-mode-probe'], 'DEBUG_MODE_STATE=')
    assert not guard['failures'] and guard['launch_debug'] and guard['file_isolation'] == 'PASS'
    assert not any((data / name).exists() for name in ['journey.json', 'controller.json', 'controller.json.tmp', 'preferences.cfg'])
    fixtures = ROOT / manifest['fixtures']
    assert fixtures.resolve().is_relative_to((ROOT / 'work').resolve())
    continuations = {}
    for source in sorted(fixtures.glob('*.json')):
        save = directory / ('continue-' + source.name)
        shutil.copy2(source, save)
        probe('continue-' + source.stem, ['--continue-smoke', '--save-path=' + str(save)])
        assert save.is_file() and Path(str(save) + '.bak').is_file()
        continuations[source.stem] = 'PASS'
    assert len(continuations) >= 8
    # Debug runs must leave existing primary/backup/temp/settings exactly intact.
    data.mkdir(parents=True, exist_ok=True)
    (data / 'controller.json').write_text(json.dumps(controllers['default_profile']))
    (data / 'controller.json.tmp').write_text('controller temporary sentinel\n')
    (data / 'preferences.cfg').write_text('[audio]\nmuted=false\nvolume=0.6\n[visual]\ngore=true\n')
    saved = directory / 'protected-journey.json'
    shutil.copy2(fixtures / 'active.json', saved)
    shutil.copy2(saved, Path(str(saved) + '.bak'))
    Path(str(saved) + '.tmp').write_text('save temporary sentinel\n')
    protected = [saved, Path(str(saved) + '.bak'), Path(str(saved) + '.tmp'), data / 'controller.json', data / 'controller.json.tmp', data / 'preferences.cfg']
    before = {str(p): digest(p) for p in protected}
    probe('protected-debug-continue', ['--debug', '--continue-smoke', '--save-path=' + str(saved)])
    guard_existing = probe('protected-debug-guard', ['--debug', '--debug-mode-probe', '--save-path=' + str(saved)], 'DEBUG_MODE_STATE=')
    assert not guard_existing['failures']
    practice_existing = probe('protected-practice', ['--debug', '--practice-probe', '--save-path=' + str(saved)], 'PRACTICE_STATE=')
    assert not practice_existing['failures'] and practice_existing['replays'] == practice['replays']
    assert {str(p): digest(p) for p in protected} == before
    standalone = directory / 'standalone'
    standalone.mkdir()
    executable = standalone / binary.name
    shutil.copy2(binary, executable)
    probe('standalone', ['--smoke'], executable=executable, case_env=isolated_env(standalone), cwd=standalone)
    network = verify_network(binary, directory / 'network')
    report = {'result': 'PASS', 'stem': settings['stem'], 'build_manifest_sha256': digest(manifest_path),
              'source_suites': manifest['source_suites'], 'normal_launch': normal,
              'linux_release': {'controllers': controllers, 'layered_graphics': layers, 'practice': practice, 'network_duels': network, 'party': party['checks'], 'debug_guards': guard['checks'],
                                'continuations': continuations, 'existing_debug_files_unchanged': len(protected), 'standalone': 'PASS'},
              'logs': str(directory.relative_to(ROOT)),
              'limits': {'Linux_graphical_playtest': 'NOT_RUN', 'physical_controllers': 'NOT_RUN: injected input only',
                         'Windows_runtime': 'NOT_RUN: export only', 'original_game_comparison': 'NOT_RUN'}}
    (ROOT / 'outputs' / (settings['artifact_id'] + '-verification.json')).write_text(json.dumps(report, indent=2) + '\n')
    print(f'PASS: actual Linux release, {len(continuations)} current save fixtures, debug isolation, controller checks, eight unchanged combat traces and standalone startup.')


if __name__ == '__main__':
    main()
